Lemma ts_lw_fact8 : forall {R : Type} A s a v (k : word -> M R) (P : R -> mstate -> Prop),
  WF A -> Rep A (ms_mem s) -> WIN s -> has A (FCT a 8 v) -> 0 <= v ->
  tsafe (k (w32 v) s) P ->
  tsafe ((x <- m_lw (Z_to_bv 64 a) ;; k x) s) P.
Proof using MLok.
